(function(g){'use strict';var KEY='hooklab_evidence_ledger_v0_1',ST=['MEASURED','DERIVED','AI_INFERRED','AUTHOR_PROVIDED','HUMAN_AUDITED','ADMITTED','REJECTED'];function load(){try{return JSON.parse(localStorage.getItem(KEY))||{schema:'HOOKLAB_EVIDENCE_LEDGER_v0.1',entries:[]}}catch(e){return{schema:'HOOKLAB_EVIDENCE_LEDGER_v0.1',entries:[]}}}function append(x){if(!x||!x.case_id||!x.state||!ST.includes(x.state))throw Error('INVALID_LEDGER_ENTRY');if(!x.producer)throw Error('PRODUCER_REQUIRED');var l=load(),e=Object.assign({},x,{ledger_id:'EL-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),recorded_at:new Date().toISOString()});l.entries.push(e);localStorage.setItem(KEY,JSON.stringify(l));return e}function byCase(id){return load().entries.filter(x=>x.case_id===id)}g.HookLabEvidenceLedger={version:'0.1',states:ST.slice(),load:load,append:append,byCase:byCase}})(window);